import * as L from 'leaflet';
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
// eslint-disable-next-line @typescript-eslint/no-require-imports
require('leaflet-hotline')(L);

type HotlineLatLng = [number, number, number];

interface HotlineOptions {
  weight?: number;
  outlineWidth?: number;
  outlineColor?: string;
  palette?: { [stop: number]: string };
  min?: number;
  max?: number;
}

export const getLeafletHotlineAsPolyline = (
  data: HotlineLatLng[],
  options: HotlineOptions & L.PolylineOptions & { distanceMarkers: any },
): L.Polyline => {
  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  // @ts-ignore
  const hotlineLayer = L.hotline(data, options);

  return hotlineLayer;
};
