import React from 'react';

import * as L from 'leaflet';
import 'leaflet-geometryutil';
import crEl from 'xneek-crel';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { getLeafletHotlineAsPolyline } from '@apps/Routes/@helpers/leafletHotline.helper';
import ElevationChart from '@apps/Routes/RouteEditorNew/components/Elevation/ElevationChart';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import { getDistanceBetweenPointsInMeters } from '@helpers/gpsHelper';
import { getForestTileLayer, getMap } from '@helpers/leafletHelper';
import { round } from '@helpers/mathHelper';

import styles from './style.module.less';
import { IHikingGpxPoint } from '../../../Hiking/@types/hiking.types';
import { getDivIcon } from '../../../Routes/@helpers/leaflet.helper';
import { IMapType } from '../../../Routes/@types/routes.types';
import '../../../../lib/leaflet-distance-markers/leaflet-distance-marker';
import '../../../../lib/leaflet-distance-markers/leaflet-distance-marker.css';

interface IWorkoutChartsProps {
  trackPoints: IHikingGpxPoint[];
  height?: number | string;
  mapType?: IMapType;
}

const WorkoutCharts: React.FC<IWorkoutChartsProps> = ({ trackPoints, mapType, height = 320 }) => {
  const eleSvgRef = React.useRef<SVGSVGElement>(null);
  const hrSvgRef = React.useRef<SVGSVGElement>(null);
  const tempSvgRef = React.useRef<SVGSVGElement>(null);

  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const markerRef = React.useRef<L.Marker>(new L.Marker([0, 0], { icon: getDivIcon() }));
  const layerGroupRef = React.useRef<L.FeatureGroup>(L.featureGroup());

  React.useEffect(() => {
    if (!ref.current) return;
    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement);
      if (mapType) {
        L.tileLayer(mapType.tileUrlTmpl).addTo(mapRef.current);
      } else {
        getForestTileLayer().addTo(mapRef.current);
      }
      watermarkToMap(mapRef.current);
      layerGroupRef.current.addTo(mapRef.current);
    }

    // const pl = new L.Polyline(
    //   trackPoints.map((x) => [x.point[0], x.point[1]]),
    //   {
    //     //@ts-expect-error
    //     distanceMarkers: { offset: 1000, cssClass: styles.kmPoint, iconSize: [16, 16] },
    //     color: '#ff0000',
    //     weight: 2,
    //     opacity: 1,
    //   },
    // );

    // pl.addTo(mapRef.current);

    layerGroupRef.current.clearLayers();

    let minSp = 500;
    let maxSp = 0;
    let sumSp = 0;

    const speeds = trackPoints.reduce<number[]>((acc, cur, i, all) => {
      if (i === 0) {
        acc.push(0);
        return acc;
      }
      const prev = all[i - 1];
      const distFromPrev = getDistanceBetweenPointsInMeters(prev.point, cur.point);
      const secFromPrev = (cur.date.getTime() - prev.date.getTime()) / 1000;
      const speed = (distFromPrev / secFromPrev) * 3.6;
      if (speed < minSp) minSp = speed;
      if (speed > maxSp) maxSp = speed;
      sumSp += speed;
      acc.push(speed);

      return acc;
    }, []);

    const avgSp = sumSp / trackPoints.length;

    const hotlineLayer = getLeafletHotlineAsPolyline(
      trackPoints.map((x, i) => [x.point[0], x.point[1], speeds[i]]),
      {
        min: avgSp * 0.2,
        max: avgSp * 1.8,
        palette: {
          [0]: '#ff0000',
          [0.5]: '#eeee00',
          [1]: '#008800',
        },
        weight: 2,
        outlineColor: '#000',
        outlineWidth: 0.5,
        distanceMarkers: { offset: 1000, cssClass: styles.kmPoint, iconSize: [16, 16] },
      },
    );

    hotlineLayer.addTo(layerGroupRef.current);

    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    const legend = L.control({ position: 'bottomright' });
    legend.onAdd = function () {
      const div = crEl(
        'div',
        { c: 'card p-1' },
        crEl(
          'div',
          { c: 'd-flex justify-content-between', s: { lineHeight: '0.8' } },
          crEl('small', round(avgSp * 0.2, 1).toLocaleString()),
          crEl('small', { c: 'text-muted' }, round(avgSp, 1).toLocaleString()),
          crEl('small', round(avgSp * 1.8, 1).toLocaleString()),
        ),
        crEl('div', {
          s: {
            height: '3px',
            width: '100px',
            background: `linear-gradient(90deg, #ff0000, #eeee00, #008800)`,
          },
        }),
        crEl(
          'div',
          { c: 'd-flex justify-content-between', s: { lineHeight: '0.8' } },
          crEl('small', ''),
          crEl('small', { c: 'text-muted' }, 'км/ч'),
          crEl('small', ''),
        ),
      );
      //div.innerHTML = 'ololo';
      return div;
    };
    legend.addTo(mapRef.current);

    L.circleMarker(trackPoints[0].point, { radius: 5, color: 'green', weight: 2 }).addTo(
      layerGroupRef.current,
    );
    L.circleMarker(trackPoints[trackPoints.length - 1].point, {
      radius: 5,
      color: 'red',
      weight: 2,
    }).addTo(layerGroupRef.current);

    mapRef.current.fitBounds(hotlineLayer.getBounds());
    mapRef.current.scrollWheelZoom.disable();
    hotlineLayer.bringToFront();

    return () => {
      layerGroupRef.current.clearLayers();
    };
  }, []);

  const updateRef = (targetSvg: SVGSVGElement, e: MouseEvent) => {
    const curEl = e.target as SVGSVGElement;
    const currentRect = curEl.getBoundingClientRect();
    const targetRect = targetSvg.getBoundingClientRect();

    const syntheticEvent = new MouseEvent('mousemove', {
      clientX: targetRect.left + (e.clientX - currentRect.left),
      clientY: targetRect.top + (e.clientY - currentRect.top),
    });

    targetSvg.dispatchEvent(syntheticEvent);
  };

  const handleChartMouseMove = (
    point: [number, number, number],
    distance: number,
    _time: number,
    e: MouseEvent,
  ) => {
    markerRef.current.setLatLng(point);
    markerRef.current.bindTooltip(formatAltitude(point[2]) + '<br>' + formatDistance(distance));
    markerRef.current.openTooltip();

    window.requestAnimationFrame(() => {
      hrSvgRef.current && updateRef(hrSvgRef.current, e);
      tempSvgRef.current && updateRef(tempSvgRef.current, e);
    });
  };

  const handleStartCursorMove = () => {
    mapRef.current && markerRef.current.addTo(mapRef.current);
    if (hrSvgRef.current) hrSvgRef.current.dispatchEvent(new MouseEvent('mouseenter'));
    if (tempSvgRef.current) tempSvgRef.current.dispatchEvent(new MouseEvent('mouseenter'));
  };

  const handleEndCursorMove = () => {
    mapRef.current && markerRef.current.removeFrom(mapRef.current);
    if (hrSvgRef.current) hrSvgRef.current.dispatchEvent(new MouseEvent('mouseleave'));
    if (tempSvgRef.current) tempSvgRef.current.dispatchEvent(new MouseEvent('mouseleave'));
  };

  return (
    <section>
      <div ref={ref} style={{ height }} />
      <details className="mt-3">
        <summary>Графики</summary>
        <div style={{ color: 'red' }}>
          <ElevationChart
            points={
              trackPoints.map((x) => [x.point[0], x.point[1], x.point[2]]) as [
                number,
                number,
                number,
              ][]
            }
            timestamps={trackPoints.map((t) => t.date.getTime())}
            timeFormatter={(x) => new Date(x).toLocaleString()}
            ref={eleSvgRef}
            onCursorMove={handleChartMouseMove}
            onEndCursorMove={handleEndCursorMove}
            onStartCursorMove={handleStartCursorMove}
          />
        </div>
        {trackPoints.some((x) => x.hr) && (
          <div style={{ color: 'blue' }}>
            <ElevationChart
              points={
                trackPoints.map((x) => [x.point[0], x.point[1], Math.round(x.hr || 100)]) as [
                  number,
                  number,
                  number,
                ][]
              }
              ref={hrSvgRef}
              timestamps={trackPoints.map((t) => t.date.getTime())}
              timeFormatter={(x) => new Date(x).toLocaleString()}
              valueFormater={(v) => `${Math.round(v)}уд`}
            />
          </div>
        )}
        {trackPoints.some((x) => x.temp && x.temp > -127) && (
          <div style={{ color: 'orange' }}>
            <ElevationChart
              points={
                trackPoints.map((x) => [x.point[0], x.point[1], round(x.temp ?? 0)]) as [
                  number,
                  number,
                  number,
                ][]
              }
              ref={tempSvgRef}
              valueFormater={(v) => `${round(v)}℃`}
              timestamps={trackPoints.map((t) => t.date.getTime())}
              timeFormatter={(x) => new Date(x).toLocaleString()}
            />
          </div>
        )}
      </details>
    </section>
  );
};

export default WorkoutCharts;
