import React, { FormEvent } from 'react';

import { editWorkoutPhotoAsync } from '@apps/Workouts/@services/workoutsPhoto.service';
import { IWorkoutPhotoUpdateDTO } from '@apps/Workouts/@types/DTO/workouts.dto.types';
import { IWorkoutPhotoFull } from '@apps/Workouts/@types/workouts.types';
import { getInputDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IWorkoutPhotoEditFormProps {
  photo: IWorkoutPhotoFull;
  id_workout: number;
  callback: (newPhoto: IWorkoutPhotoFull) => void;
}

const WorkoutPhotoEditForm: React.FC<IWorkoutPhotoEditFormProps> = ({ photo, callback }) => {
  const [data, setData] = React.useState<IWorkoutPhotoUpdateDTO>({
    id_photo: photo.id,
    is_main: photo.is_main ? '1' : '0',
    date: getInputDate(photo.date),
    comment: photo.comment,
  });

  const [isSaving, setIsSaving] = React.useState(false);

  type T = Pick<IWorkoutPhotoUpdateDTO, 'comment' | 'date' | 'is_main'>;

  const handleInputChange = (field: keyof T) => (value: string) => {
    setData((fd) => ({
      ...fd,
      [field]: value,
    }));
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      await editWorkoutPhotoAsync(data);
      callback({
        ...photo,
        comment: data.comment,
      });
      notificationHelper.success('Сохранено');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <PohRow className="mb-2">
        <PohCol sm={2}>Фото</PohCol>
        <PohCol sm={10}>
          <img src={photo.url} width={'100%'} />
        </PohCol>
      </PohRow>
      <PohRow className="mb-2">
        <PohCol sm={2}>&nbsp;</PohCol>
        <PohCol sm={10}>
          <PohCheckbox
            disabled={isSaving}
            label="Основное фото"
            checked={data.is_main === '1'}
            onChange={(v) => handleInputChange('is_main')(v ? '1' : '0')}
          />
        </PohCol>
      </PohRow>

      <PohInput
        type={InputTypes.textarea}
        disabled={isSaving}
        label="Комментарий"
        horizontal
        wrapperClassName="mb-3"
        value={data.comment}
        onChange={handleInputChange('comment')}
      />

      <footer className="border-top p-3 text-end">
        <PohButton type="submit" disabled={isSaving}>
          Сохранить
        </PohButton>
      </footer>
    </form>
  );
};

export default WorkoutPhotoEditForm;
